pragma solidity ^0.4.15;

contract OwnerBox{
    address private authority;

    modifier onlyAuthority {
        require(msg.sender==authority);
        _;
    }

    function OwnerBox()
        public 
    {
        authority = msg.sender;
    }

    // This function should be protected
    function assignAuthority(address _newOwner) 
        public
    {
       authority = _newOwner;
    }

    function assignAuthoritySafe(address _newOwner) 
        public 
        onlyAuthority
    {
       authority = _newOwner;
    }
}
